552	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
553		v := &BatchView{
554			BatchNo:         b.BatchNo,
555			RecipeNo:        r.RecipeNo,
556			RecipeVersion:   r.Version,
557			RecipeName:      r.Name,
558			PlannedPortions: b.PlannedPortions,
559			Status:          b.Status,
560			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
561			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
562		}
563	
564		for _, f := range b.Feedings {
565			v.Feedings = append(v.Feedings, FeedingView{
566				Seq:        f.Seq,
567				MaterialNo: f.MaterialNo,
568				Grams:      f.GramsMilli.String(),
569				Time:       f.Time,
570				Registrar:  f.Registrar,
571			})
572		}
