1	package release
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件为“投料”（AddFeeding）补充请求编号与投料内容一致性的回归测试，
10	// 保护一笔已经成功登记的投料：
11	//   - 用原请求编号与原内容再次提交，只能取回第一次成功登记的那条记录，
12	//     即使其间已经追加了其他投料，也不能把最近一笔投料误当成原记录，
13	//     更不能重复计入实投量；
14	//   - 沿用已成功的请求编号时，批次、物料、克数字符串、投料时间、登记人
15	//     任一项改变，都必须返回可用 errors.Is 判断的 ErrRequestConflict，
16	//     且这些“不同内容”本身都符合投料条件（改投同一配方内的另一物料、
17	//     换一个合法数量、更换登记人等），不靠非法输入被拒绝来冒充冲突；
18	//   - 克数的显示格式与请求内容要分清：“1.000”成功后显示“1”，但再次
19	//     提交只有仍带“1.000”才算同一内容，改成数值相等的“1”仍是冲突；
20	//   - 请求编号在同一台账内共用，另一个执行中的批次也不能沿用；
21	//   - 冲突不覆盖、不追加、不占用下一个登记序号；冲突之后原内容仍能用原
22	//     编号取得第一次的结果，而换用新请求编号提交相同内容则是独立的一笔，
23	//     正常追加并取得连续的下一个序号。
24	
25	// feedingReplayTime 是投料回归测试使用的固定时间基。
26	func feedingReplayTime() time.Time {
27		return time.Date(2026, 10, 5, 8, 0, 0, 0, time.UTC)
28	}
29	
30	// checkFeedingView 逐条核对一条投料视图的序号、物料、显示克数、时间与登记人。
31	func checkFeedingView(t *testing.T, f *FeedingView, seq int, material, grams string, tm time.Time, registrar string) {
32		t.Helper()
33		if f.Seq != seq || f.MaterialNo != material || f.Grams != grams ||
34			!f.Time.Equal(tm) || f.Registrar != registrar {
35			t.Fatalf("投料视图应为 序号=%d 物料=%s 克数=%s 时间=%s 登记人=%s，得到 %+v",
36				seq, material, grams, tm.Format(time.RFC3339), registrar, f)
37		}
38	}
39	
40	// 执行中的批次成功登记一笔投料后，使用原请求编号、原批次编号、原物料、
41	// 原克数字符串、原投料时间和原登记人再次提交，应返回第一次成功登记的那条
42	// 记录。即使其间已经追加了其他投料，返回的序号、物料、数量、时间和登记人
43	// 仍属于原记录，不能变成最近一笔；批次查询中的投料条数、登记顺序和各物料
44	// 累计实投量也不能因重放而变化。重新打开台账后，重放仍返回首次结果。
45	func TestAddFeedingReplayReturnsFirstRecordAfterMoreFeedings(t *testing.T) {
46		dir := t.TempDir()
47		s, err := Open(dir)
48		if err != nil {
49			t.Fatalf("Open 失败: %v", err)
50		}
51		registerStandardRecipe(t, s, "recipe-1") // M1=100、M2=0.5、M3=0.010
52		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
53			t.Fatalf("创建批次失败: %v", err)
54		}
55		if _, err := s.StartBatch("s1", "B1"); err != nil {
56			t.Fatalf("开始执行失败: %v", err)
57		}
58	
59		t1 := feedingReplayTime()
60		// 首次提交带“1.000”，成功结果的克数显示为“1”。
61		first, err := s.AddFeeding("feed-1", "B1", "M1", "1.000", t1, "张三")
62		if err != nil {
63			t.Fatalf("首次登记投料应成功: %v", err)
64		}
65		checkFeedingView(t, first, 1, "M1", "1", t1, "张三")
66	
67		// 其间追加两笔其他投料（含另一物料与另一登记人）。
68		t2 := t1.Add(time.Hour)
69		t3 := t1.Add(2 * time.Hour)
70		second, err := s.AddFeeding("feed-2", "B1", "M2", "2", t2, "李四")
71		if err != nil {
72			t.Fatalf("追加第二笔投料失败: %v", err)
73		}
74		checkFeedingView(t, second, 2, "M2", "2", t2, "李四")
75		third, err := s.AddFeeding("feed-3", "B1", "M1", "3", t3, "王五")
76		if err != nil {
