178		}
179	
180		t1 := feedingReplayTime()
181		first, err := s.AddFeeding("feed-orig", "B1", "M1", "10", t1, "张三")
182		if err != nil {
183			t.Fatalf("首次登记投料应成功: %v", err)
184		}
