186		// 再追加一笔，占用序号 2，便于发现冲突提交是否偷偷追加或占号。
187		if _, err := s.AddFeeding("feed-other", "B1", "M2", "2", t1.Add(time.Hour), "李四"); err != nil {
188			t.Fatalf("追加第二笔投料失败: %v", err)
189		}
190	
191		// 每项都只改一处，其余与首次成功提交完全一致，且改后内容仍可正常投料。
192		cases := []struct {
193			name      string
194			batchNo   string
195			material  string
196			grams     string
197			tm        time.Time
198			registrar string
199		}{
200			{name: "改投同一配方中的另一种物料", batchNo: "B1", material: "M2", grams: "10", tm: t1, registrar: "张三"},
201			{name: "换一个合法数量", batchNo: "B1", material: "M1", grams: "11", tm: t1, registrar: "张三"},
202			{name: "更换投料时间", batchNo: "B1", material: "M1", grams: "10", tm: t1.Add(time.Minute), registrar: "张三"},
203			{name: "更换登记人", batchNo: "B1", material: "M1", grams: "10", tm: t1, registrar: "李四"},
204			{name: "改到另一个执行中的批次", batchNo: "B2", material: "M1", grams: "10", tm: t1, registrar: "张三"},
205		}
206		for _, tc := range cases {
207			t.Run(tc.name, func(t *testing.T) {
208				_, err := s.AddFeeding("feed-orig", tc.batchNo, tc.material, tc.grams, tc.tm, tc.registrar)
209				if !errors.Is(err, ErrRequestConflict) {
210					t.Fatalf("内容不同但沿用原请求编号应返回 ErrRequestConflict，得到 %v", err)
211				}
212			})
213	
214			// 每次冲突后 B1 都保持原样：仍是 2 条投料、顺序不变，
215			// M1 累计仍为 10、M2 累计仍为 2，冲突内容没有被追加或覆盖。
216			view := mustGetBatch(t, s, "B1")
217			if len(view.Feedings) != 2 {
218				t.Fatalf("%s：冲突不应追加投料，B1 应仍为 2 条，得到 %d 条: %+v",
219					tc.name, len(view.Feedings), view.Feedings)
220			}
221			checkFeedingView(t, &view.Feedings[0], 1, "M1", "10", t1, "张三")
222			checkFeedingView(t, &view.Feedings[1], 2, "M2", "2", t1.Add(time.Hour), "李四")
223			b1Mats := materialsMap(view)
224			checkRequirement(t, b1Mats, "M1", "1000", "10", "-990")
225			checkRequirement(t, b1Mats, "M2", "5", "2", "-3")
226			checkRequirement(t, b1Mats, "M3", "0.1", "0", "-0.1")
227	
228			// 下一个登记序号不能被冲突占用：B2 的“改批次”冲突同样不能落进 B2。
229			b2 := mustGetBatch(t, s, "B2")
230			if len(b2.Feedings) != 0 {
231				t.Fatalf("%s：冲突不应在 B2 追加投料，得到 %d 条: %+v",
232					tc.name, len(b2.Feedings), b2.Feedings)
233			}
234		}
